import 'package:flutter_test/flutter_test.dart';
import 'package:ukulele_groove/data.dart';
void main(){test('Every lesson has an available best-fit pattern and playable cycle',(){expect(lessons.length,5);for(final lesson in lessons){final best=patterns.firstWhere((p)=>p['id']==lesson['best']);expect(best['meter'],lesson['meter']);expect((best['steps'] as List).length,(lesson['meter'] as int)*2);expect(lesson['options'] as List,contains(lesson['best']));}});test('Skips and mutes stay different',(){final island=patterns.firstWhere((p)=>p['id']=='island');final chuck=patterns.firstWhere((p)=>p['id']=='chuck');expect(island['steps'],contains('-'));expect(chuck['steps'],contains('X'));});}
